// Shadcn carousel (embla-carousel-react) — adapted for non-Tailwind environment.
import * as React from 'react';
import useEmblaCarousel, { type UseEmblaCarouselType } from 'embla-carousel-react';
import { ArrowLeft, ArrowRight } from 'lucide-react';
import { cn } from '../../lib/utils';
import { Button } from './button';

export type CarouselApi = UseEmblaCarouselType[1];
type CarouselOptions = Parameters<typeof useEmblaCarousel>[0];
type CarouselPlugin  = Parameters<typeof useEmblaCarousel>[1];

type CarouselProps = {
  opts?:        CarouselOptions;
  plugins?:     CarouselPlugin;
  orientation?: 'horizontal' | 'vertical';
  setApi?:      (api: CarouselApi) => void;
};

type CarouselContextProps = {
  carouselRef:    ReturnType<typeof useEmblaCarousel>[0];
  api:            CarouselApi;
  scrollPrev:     () => void;
  scrollNext:     () => void;
  canScrollPrev:  boolean;
  canScrollNext:  boolean;
} & CarouselProps;

const CarouselContext = React.createContext<CarouselContextProps | null>(null);

function useCarousel() {
  const ctx = React.useContext(CarouselContext);
  if (!ctx) throw new Error('useCarousel must be used within <Carousel />');
  return ctx;
}

// ── Carousel ──────────────────────────────────────────────────────────────────

export const Carousel = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & CarouselProps
>(({ orientation = 'horizontal', opts, setApi, plugins, className, children, ...props }, ref) => {
  const [carouselRef, api] = useEmblaCarousel(
    { ...opts, axis: orientation === 'horizontal' ? 'x' : 'y' },
    plugins,
  );
  const [canScrollPrev, setCanScrollPrev] = React.useState(false);
  const [canScrollNext, setCanScrollNext] = React.useState(false);

  const onSelect = React.useCallback((api: CarouselApi) => {
    if (!api) return;
    setCanScrollPrev(api.canScrollPrev());
    setCanScrollNext(api.canScrollNext());
  }, []);

  const scrollPrev = React.useCallback(() => api?.scrollPrev(), [api]);
  const scrollNext = React.useCallback(() => api?.scrollNext(), [api]);

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (e.key === 'ArrowLeft')  { e.preventDefault(); scrollPrev(); }
      if (e.key === 'ArrowRight') { e.preventDefault(); scrollNext(); }
    },
    [scrollPrev, scrollNext],
  );

  React.useEffect(() => { if (api && setApi) setApi(api); }, [api, setApi]);

  React.useEffect(() => {
    if (!api) return;
    onSelect(api);
    api.on('reInit', onSelect);
    api.on('select', onSelect);
    return () => {
      api.off('reInit', onSelect);
      api.off('select', onSelect);
    };
  }, [api, onSelect]);

  return (
    <CarouselContext.Provider value={{
      carouselRef, api, opts, orientation,
      scrollPrev, scrollNext, canScrollPrev, canScrollNext,
    }}>
      <div
        ref={ref}
        onKeyDownCapture={handleKeyDown}
        className={cn('carousel', className)}
        role="region"
        aria-roledescription="carousel"
        {...props}
      >
        {children}
      </div>
    </CarouselContext.Provider>
  );
});
Carousel.displayName = 'Carousel';

// ── CarouselContent ───────────────────────────────────────────────────────────

export const CarouselContent = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => {
  const { carouselRef, api } = useCarousel();
  const viewportRef = React.useRef<HTMLDivElement | null>(null);

  const setViewportRef = React.useCallback(
    (node: HTMLDivElement | null) => {
      viewportRef.current = node;
      carouselRef(node);
    },
    [carouselRef],
  );

  React.useLayoutEffect(() => {
    if (!api) return;
    const el = viewportRef.current;
    if (!el) return;
    if (typeof ResizeObserver === 'undefined') {
      api.reInit();
      return;
    }
    const ro = new ResizeObserver(() => {
      api.reInit();
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [api]);

  return (
    <div ref={setViewportRef} className="carousel__viewport">
      <div ref={ref} className={cn('carousel__track', className)} {...props} />
    </div>
  );
});
CarouselContent.displayName = 'CarouselContent';

// ── CarouselItem ──────────────────────────────────────────────────────────────

export const CarouselItem = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    role="group"
    aria-roledescription="slide"
    className={cn('carousel__item', className)}
    {...props}
  />
));
CarouselItem.displayName = 'CarouselItem';

// ── CarouselPrevious ──────────────────────────────────────────────────────────

export const CarouselPrevious = React.forwardRef<
  HTMLButtonElement,
  React.ComponentProps<typeof Button>
>(({ className, variant = 'outline', ...props }, ref) => {
  const { scrollPrev, canScrollPrev } = useCarousel();
  return (
    <Button
      ref={ref}
      variant={variant}
      className={cn('carousel__nav-btn carousel__nav-btn--prev', className)}
      disabled={!canScrollPrev}
      onClick={scrollPrev}
      {...props}
    >
      <ArrowLeft size={14} />
      <span className="scn-sr-only">Previous slide</span>
    </Button>
  );
});
CarouselPrevious.displayName = 'CarouselPrevious';

// ── CarouselNext ──────────────────────────────────────────────────────────────

export const CarouselNext = React.forwardRef<
  HTMLButtonElement,
  React.ComponentProps<typeof Button>
>(({ className, variant = 'outline', ...props }, ref) => {
  const { scrollNext, canScrollNext } = useCarousel();
  return (
    <Button
      ref={ref}
      variant={variant}
      className={cn('carousel__nav-btn carousel__nav-btn--next', className)}
      disabled={!canScrollNext}
      onClick={scrollNext}
      {...props}
    >
      <ArrowRight size={14} />
      <span className="scn-sr-only">Next slide</span>
    </Button>
  );
});
CarouselNext.displayName = 'CarouselNext';
